  if(!base&&!modelBlob||id.startsWith('local-')&&!modelBlob)throw Error('A new companion must include its model.');const entry={...base,id,name,sex,...p,personality:{...base?.personality,...p.personality},model:modelBlob?'local-model-'+id:base.model,voice:base?.voice||{characterId:'vr-'+id,pending:true}};if(modelBlob){delete entry.file;delete entry.preview;delete entry.looks;}
